const balancer = new Balancer(
  [new URL("http://127.0.0.1:3000"), new URL("http://127.0.0.1:3001")],
  "round-robin",
);
const lease = balancer.acquire(); // lease.target.url is the chosen upstream

private pickRoundRobin(): Target {
  const index = this.next % this.targets.length;
  this.next = index + 1;
  return this.targets[index]!;
}

for (let step = 1; step < n; step++) {
